PRAGMA journal_mode=WAL;
PRAGMA synchronous=FULL;
CREATE TABLE IF NOT EXISTS meta(key TEXT PRIMARY KEY,value TEXT NOT NULL) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS recordings(id TEXT PRIMARY KEY,context TEXT NOT NULL,seq INTEGER NOT NULL DEFAULT 0,watermark INTEGER NOT NULL DEFAULT 0,state TEXT NOT NULL DEFAULT 'recording',commit_id TEXT NOT NULL DEFAULT '') WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS executions(recording TEXT NOT NULL,id TEXT NOT NULL,PRIMARY KEY(recording,id)) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS content_refs(recording TEXT NOT NULL,target TEXT NOT NULL,commit_id TEXT NOT NULL,PRIMARY KEY(recording,target,commit_id)) WITHOUT ROWID;
CREATE INDEX IF NOT EXISTS content_ref_target ON content_refs(target,recording);
CREATE INDEX IF NOT EXISTS execution_recordings ON executions(id,recording);
CREATE TABLE IF NOT EXISTS streams(recording TEXT NOT NULL,id INTEGER NOT NULL,topic TEXT NOT NULL,symbol TEXT NOT NULL,PRIMARY KEY(recording,id)) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS blocks(recording TEXT NOT NULL,id INTEGER NOT NULL,stream INTEGER NOT NULL,offset INTEGER NOT NULL,length INTEGER NOT NULL,raw_length INTEGER NOT NULL,sha256 TEXT NOT NULL,first_seq INTEGER NOT NULL,last_seq INTEGER NOT NULL,positions BLOB NOT NULL DEFAULT X'',PRIMARY KEY(recording,id)) WITHOUT ROWID;
CREATE INDEX IF NOT EXISTS blocks_stream_sequence ON blocks(recording,stream,first_seq,id);
CREATE TABLE IF NOT EXISTS location_pages(recording TEXT NOT NULL,first_seq INTEGER NOT NULL,last_seq INTEGER NOT NULL,first_time INTEGER NOT NULL,last_time INTEGER NOT NULL,positions BLOB NOT NULL,PRIMARY KEY(recording,first_seq));
CREATE INDEX IF NOT EXISTS location_time ON location_pages(recording,first_time,first_seq);
CREATE TABLE IF NOT EXISTS objects(id INTEGER PRIMARY KEY,recording TEXT NOT NULL,kind TEXT NOT NULL,key TEXT NOT NULL,first_seq INTEGER,UNIQUE(recording,kind,key));
CREATE INDEX IF NOT EXISTS objects_page ON objects(recording,kind,first_seq,id);
CREATE TABLE IF NOT EXISTS object_refs(recording TEXT NOT NULL,object INTEGER NOT NULL,seq INTEGER NOT NULL,row INTEGER NOT NULL,PRIMARY KEY(recording,object,seq,row)) WITHOUT ROWID;
CREATE INDEX IF NOT EXISTS refs_observation ON object_refs(recording,seq,object);
CREATE TABLE IF NOT EXISTS object_blocks(recording TEXT NOT NULL,object INTEGER NOT NULL,stream INTEGER NOT NULL,block INTEGER NOT NULL,first_seq INTEGER NOT NULL,last_seq INTEGER NOT NULL,PRIMARY KEY(recording,object,stream,block)) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS scope_blocks(recording TEXT NOT NULL,kind TEXT NOT NULL,symbol TEXT NOT NULL,stream INTEGER NOT NULL,block INTEGER NOT NULL,first_seq INTEGER NOT NULL,last_seq INTEGER NOT NULL,PRIMARY KEY(recording,kind,symbol,stream,block)) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS business_changes(recording TEXT NOT NULL,kind TEXT NOT NULL,seq INTEGER NOT NULL,object INTEGER NOT NULL,PRIMARY KEY(recording,kind,seq,object)) WITHOUT ROWID;
CREATE INDEX IF NOT EXISTS business_changes_object ON business_changes(recording,kind,object,seq);
CREATE TABLE IF NOT EXISTS generations(recording TEXT NOT NULL,seq INTEGER NOT NULL,generation INTEGER NOT NULL,PRIMARY KEY(recording,seq)) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS symbols(recording TEXT NOT NULL,symbol TEXT NOT NULL,first_seq INTEGER NOT NULL,PRIMARY KEY(recording,symbol)) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS query_refs(recording TEXT NOT NULL,seq INTEGER NOT NULL,PRIMARY KEY(recording,seq)) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS scope_refs(recording TEXT NOT NULL,kind TEXT NOT NULL,symbol TEXT NOT NULL,seq INTEGER NOT NULL,PRIMARY KEY(recording,kind,symbol,seq)) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS relations(recording TEXT NOT NULL,source INTEGER NOT NULL,target INTEGER NOT NULL,seq INTEGER NOT NULL,role TEXT NOT NULL,PRIMARY KEY(recording,target,role,seq,source)) WITHOUT ROWID;
CREATE INDEX IF NOT EXISTS relations_source ON relations(recording,source,role,seq,target);
CREATE INDEX IF NOT EXISTS relations_known ON relations(recording,seq);
CREATE TABLE IF NOT EXISTS order_mentions(recording TEXT NOT NULL,kind TEXT NOT NULL,order_id TEXT NOT NULL,object INTEGER NOT NULL,first_seq INTEGER NOT NULL,PRIMARY KEY(recording,kind,order_id,object)) WITHOUT ROWID;
CREATE INDEX IF NOT EXISTS order_mentions_object ON order_mentions(recording,object,order_id);
CREATE INDEX IF NOT EXISTS order_mentions_page ON order_mentions(recording,kind,order_id,first_seq,object);
CREATE TABLE IF NOT EXISTS proofs(recording TEXT NOT NULL,seq INTEGER NOT NULL,row INTEGER NOT NULL,members INTEGER NOT NULL,PRIMARY KEY(recording,seq,row)) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS proof_members(recording TEXT NOT NULL,seq INTEGER NOT NULL,row INTEGER NOT NULL,member INTEGER NOT NULL,position INTEGER NOT NULL,PRIMARY KEY(recording,seq,row,member)) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS commits(recording TEXT NOT NULL,id TEXT NOT NULL,offset INTEGER NOT NULL,seq INTEGER NOT NULL,watermark INTEGER NOT NULL,last_block INTEGER NOT NULL,PRIMARY KEY(recording,id)) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS recording_keys(id INTEGER PRIMARY KEY,recording TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS market_namespaces(id INTEGER PRIMARY KEY,recording INTEGER NOT NULL,prefix TEXT NOT NULL,UNIQUE(recording,prefix));
CREATE TABLE IF NOT EXISTS market_objects(recording INTEGER NOT NULL,first_seq INTEGER NOT NULL,kind INTEGER NOT NULL,namespace INTEGER NOT NULL,suffix TEXT NOT NULL,block INTEGER NOT NULL,line INTEGER NOT NULL,stream INTEGER NOT NULL,last_seq INTEGER NOT NULL,linked INTEGER NOT NULL,PRIMARY KEY(recording,first_seq)) WITHOUT ROWID;
CREATE UNIQUE INDEX IF NOT EXISTS market_identity ON market_objects(recording,kind,namespace,suffix);
CREATE INDEX IF NOT EXISTS market_page ON market_objects(recording,kind,namespace,first_seq);
CREATE INDEX IF NOT EXISTS namespace_page ON market_namespaces(recording,id);
CREATE TABLE IF NOT EXISTS market_namespace_symbols(namespace INTEGER NOT NULL,symbol TEXT NOT NULL,first_seq INTEGER NOT NULL,PRIMARY KEY(namespace,symbol)) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS market_refs(recording INTEGER NOT NULL,object INTEGER NOT NULL,seq INTEGER NOT NULL,known_seq INTEGER NOT NULL,block INTEGER NOT NULL,line INTEGER NOT NULL,stream INTEGER NOT NULL,PRIMARY KEY(recording,object,seq)) WITHOUT ROWID;
CREATE INDEX IF NOT EXISTS market_ref_stream ON market_refs(recording,object,stream,block);
CREATE INDEX IF NOT EXISTS market_ref_known ON market_refs(recording,object,stream,known_seq,block);
CREATE TABLE IF NOT EXISTS market_links(recording INTEGER NOT NULL,object INTEGER NOT NULL,seq INTEGER NOT NULL,known_seq INTEGER NOT NULL,PRIMARY KEY(recording,object,seq)) WITHOUT ROWID;
CREATE INDEX IF NOT EXISTS market_link_source ON market_links(recording,seq,known_seq,object);
